function infoCa_injectToCodex()
    Player():invokeFunction('ui/cosmiccodex', 'addCategory', 'ca_cat', 'Cosmic Ascendancy'%_t, 'data/textures/icons/vortex.png')
    Player():invokeFunction('ui/cosmiccodex', 'addArticle', 'ca_cat', 'ca_eclipse', 'The Eclipse'%_t, 'Following the destruction of the Wormhole Guardian, a darker, ancient adversary awakens: The Eclipse. This endgame faction commands unfathomable power and will aggressively invade the galaxy from the core outward. Their citadels are heavily fortified, and their fleets use exotic singularity weaponry.'%_t, '')
    Player():invokeFunction('ui/cosmiccodex', 'addArticle', 'ca_cat', 'ca_forge', 'The Ascendancy Forge'%_t, 'An ancient, monolithic structure unlocked during the campaign. The Forge allows you to craft Ascendant-tier technologies by sacrificing vast amounts of resources and exotic materials looted from The Eclipse. This is the only way to obtain the tools necessary to combat the awakened threat.'%_t, '')
    Player():invokeFunction('ui/cosmiccodex', 'addArticle', 'ca_cat', 'ca_campaign', 'Story Campaign'%_t, 'Ascendancy introduces a one-time epic narrative campaign. Starting near the barrier after defeating the Guardian, you will track a mysterious distress signal, uncover the truth behind The Eclipse, and unlock the secrets of Ascension. Check your mission logs to begin the journey.'%_t, '')
end
